                        /** @enum {string|null} */
                        phase?: "checking" | "recording" | null;
                        total: number;
                        done: number;
                        result?: components["schemas"]["BulkEmployeeLifecycleEventResponse"] | null;
                        /** @description {code, message, refusals?} of a failed job. */
                        error?: Record<string, never> | null;
